component NotesHttp requires store: NoteStore provides notes_api: NotesApi {
  provide notes_api {
    fn get_note(id) {
      let found = store.get(id)
      if (is_some(found)) {
        return Ok(unwrap(found))
      }
      return not_found_error("no note with that id")
    }

    fn list_notes(limit) {
      let notes = store.all()
      if (is_some(limit)) {
        return Ok(take(notes, unwrap(limit)))
      }
      return Ok(notes)
    }

    fn create_note(note) {
      let id = `note-${store.size()}`
      let row = { id: id, title: note.title, body: note.body }
      emit store.create(row)
      return Ok(row)
    }
  }
}

